#include <bits/stdc++.h>
using namespace std;

static char buf[1 << 16];
static size_t blen = 0, bpos = 0;
static inline int gc() {
    if (bpos == blen) {
        blen = fread(buf, 1, sizeof buf, stdin);
        bpos = 0;
        if (!blen) return -1;
    }
    return buf[bpos++];
}
static long long readLong() {
    int c = gc();
    while (c != '-' && (c < '0' || c > '9')) {
        if (c == -1) return 0;
        c = gc();
    }
    bool neg = false;
    if (c == '-') { neg = true; c = gc(); }
    long long v = 0;
    while (c >= '0' && c <= '9') { v = v * 10 + (c - '0'); c = gc(); }
    return neg ? -v : v;
}

int main() {
    int n = (int)readLong();
    vector<long long> threshold(n);
    for (auto &v : threshold) v = readLong();
    vector<int> head(n, -1), to(2 * (n - 1)), nxt(2 * (n - 1));
    vector<long long> weight(2 * (n - 1));
    int e = 0;
    for (int i = 0; i < n - 1; i++) {
        int u = (int)readLong() - 1, v = (int)readLong() - 1;
        long long w = readLong();
        to[e] = v; weight[e] = w; nxt[e] = head[u]; head[u] = e++;
        to[e] = u; weight[e] = w; nxt[e] = head[v]; head[v] = e++;
    }
    // Iterative DFS carrying: root distance, min distance over strict ancestors, removed flag.
    struct Item { int u, parent; long long dist, minimum; bool removed; };
    vector<Item> stack{{0, -1, 0, 0, false}};
    long long answer = 0;
    while (!stack.empty()) {
        Item it = stack.back();
        stack.pop_back();
        bool removed = it.removed || (it.u != 0 && it.dist - it.minimum > threshold[it.u]);
        answer += removed;
        long long minimum = min(it.minimum, it.dist);
        for (int x = head[it.u]; x != -1; x = nxt[x])
            if (to[x] != it.parent) stack.push_back({to[x], it.u, it.dist + weight[x], minimum, removed});
    }
    printf("%lld\n", answer);
}

import java.io.*;

public class Main {
    static final InputStream in = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int gc() throws IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = gc();
        while (c != '-' && (c < '0' || c > '9')) {
            if (c == -1) return 0;
            c = gc();
        }
        boolean neg = false;
        if (c == '-') { neg = true; c = gc(); }
        long v = 0;
        while (c >= '0' && c <= '9') { v = v * 10 + (c - '0'); c = gc(); }
        return neg ? -v : v;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long[] threshold = new long[n];
        for (int i = 0; i < n; i++) threshold[i] = nextLong();
        int[] head = new int[n], to = new int[2 * (n - 1)], nxt = new int[2 * (n - 1)];
        long[] weight = new long[2 * (n - 1)];
        java.util.Arrays.fill(head, -1);
        int e = 0;
        for (int i = 0; i < n - 1; i++) {
            int u = (int) nextLong() - 1, v = (int) nextLong() - 1;
            long w = nextLong();
            to[e] = v; weight[e] = w; nxt[e] = head[u]; head[u] = e++;
            to[e] = u; weight[e] = w; nxt[e] = head[v]; head[v] = e++;
        }
        // Iterative DFS carrying: root distance, min distance over strict ancestors, removed flag.
        int[] su = new int[n], sp = new int[n];
        long[] sd = new long[n], sm = new long[n];
        boolean[] sr = new boolean[n];
        int top = 0;
        su[0] = 0; sp[0] = -1; sd[0] = 0; sm[0] = 0; sr[0] = false; top = 1;
        long answer = 0;
        while (top > 0) {
            top--;
            int u = su[top], parent = sp[top];
            long dist = sd[top], minimum = sm[top];
            boolean removed = sr[top] || (u != 0 && dist - minimum > threshold[u]);
            if (removed) answer++;
            minimum = Math.min(minimum, dist);
            for (int x = head[u]; x != -1; x = nxt[x]) {
                if (to[x] != parent) {
                    su[top] = to[x]; sp[top] = u; sd[top] = dist + weight[x]; sm[top] = minimum; sr[top] = removed;
                    top++;
                }
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<16)

func readInt() int64 {
	c, err := rd.ReadByte()
	for err == nil && c != '-' && (c < '0' || c > '9') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return 0
	}
	neg := false
	if c == '-' {
		neg = true
		c, err = rd.ReadByte()
	}
	var v int64
	for err == nil && c >= '0' && c <= '9' {
		v = v*10 + int64(c-'0')
		c, err = rd.ReadByte()
	}
	if neg {
		return -v
	}
	return v
}

type item struct {
	u, parent     int32
	dist, minimum int64
	removed       bool
}

func main() {
	n := int(readInt())
	threshold := make([]int64, n)
	for i := range threshold {
		threshold[i] = readInt()
	}
	head := make([]int32, n)
	for i := range head {
		head[i] = -1
	}
	to, nxt := make([]int32, 2*(n-1)), make([]int32, 2*(n-1))
	weight := make([]int64, 2*(n-1))
	e := int32(0)
	for i := 0; i < n-1; i++ {
		u, v := int32(readInt()-1), int32(readInt()-1)
		w := readInt()
		to[e], weight[e], nxt[e], head[u] = v, w, head[u], e
		e++
		to[e], weight[e], nxt[e], head[v] = u, w, head[v], e
		e++
	}
	// Iterative DFS carrying: root distance, min distance over strict ancestors, removed flag.
	stack := []item{{0, -1, 0, 0, false}}
	answer := 0
	for len(stack) > 0 {
		it := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		removed := it.removed || (it.u != 0 && it.dist-it.minimum > threshold[it.u])
		if removed {
			answer++
		}
		minimum := min(it.minimum, it.dist)
		for x := head[it.u]; x != -1; x = nxt[x] {
			if to[x] != it.parent {
				stack = append(stack, item{to[x], it.u, it.dist + weight[x], minimum, removed})
			}
		}
	}
	fmt.Println(answer)
}
